/// <summary>
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(classStr(PriceDiscAdmCheckPost))]
final class METPriceDiscAdmCheckPost_Extension
{
}

Method.Source:
    /// <summary>
    /// post Journal extension
    /// </summary>
    void postJournal()
    {
        next postJournal();

        if(this.isPosted() && GUPParameters::find().METPriceChangeTrackingEnable)
        {
            PriceDiscAdmTable priceDiscAdmTable = PriceDiscAdmTable::find(journalNum);

            Global::runAsync(classNum(METPriceChangeEventManage),
                            staticMethodStr(METPriceChangeEventManage, processEvent),
                            [METPriceChangeType::TradeAgreement, priceDiscAdmTable, SysAppCRUDOperation::Create],
                            System.Threading.CancellationToken::None,
                            classNum(METPriceChangeEventManage),
                            staticMethodStr(METPriceChangeEventManage, callBackResult));
        }
    }
